s($,"e2s","aPI",()=>new A.bsT(A.aq("[/\\\\]",!0,!1,!1,!1),A.aq("[^/\\\\]$",!0,!1,!1,!1),A.aq("^(\\\\\\\\[^\\\\]+\\\\[^\\\\/]+|[a-zA-Z]:[/\\\\])",!0,!1,!1,!1),A.aq("^[/\\\\](?![/\\\\])",!0,!1,!1,!1)))
s($,"e2r","ail",()=>new A.brY(A.aq("/",!0,!1,!1,!1),A.aq("(^[a-zA-Z][-+.a-zA-Z\\d]*://|[^/])$",!0,!1,!1,!1),A.aq("[a-zA-Z][-+.a-zA-Z\\d]*://[^/]*",!0,!1,!1,!1),A.aq("^/",!0,!1,!1,!1)))
